import {incrementalRecord} from './incremental-registry.js';
import {incrementalIdentityValid} from './incremental-research-identity.js';
import {evaluateRmbs,RMBS_ERROR} from './rmbs-financial-engine.js';
const finite=x=>typeof x==='number'&&Number.isFinite(x),fail=()=>{throw Error(RMBS_ERROR);};
export function rmbsContext(d){
 const r=incrementalRecord(d?.ticker);if(!r||d.ticker!=='RMBS'||!incrementalIdentityValid(d)||d.schemaVersion!==1||d.forecastHorizonYears!==10||d.annual?.length!==10||d.timing?.mode!=='origin'||d.discountOrigin!=='2026-06-30'||d.timing.asOf!=='2026-10-19'||d.timing.stubFCFF!==null||Object.keys(d.bridgeInputs||{}).length)fail();
 const c=d.selectedIncrementalScenario?r.alternatives.find(a=>a.name===d.selectedIncrementalScenario)?.annualCase:r.annualCase;if(!c)fail();
 for(let i=0;i<10;i++)if(d.annual[i].year!==i+1||d.annual[i].period!==c.annual[i].period||!['revenue','margin','taxRate','reinvestment','wacc'].every(k=>finite(d.annual[i][k])))fail();
 if(d.rmbsAwardPolicy===undefined)fail();
 const result=evaluateRmbs(r.sourceInputs,r.sourceInputs.scenarios[c.sourceScenario],d.rmbsAwardPolicy,d.annual,d.terminal);return {r,c,result};
}
export function calculateRmbsOperating(d){
 const {r,result:v}=rmbsContext(d);let prior=d.anchor.revenue;
 const rows=v.rows.map((row,i)=>{const delta=row.revenue-prior;prior=row.revenue;return {...d.annual[i],...row,period:d.annual[i].period,margin:row.ebit_margin,ebit:row.revenue*row.ebit_margin+row.legacy_expense_removed,nopat:row.nopat+row.legacy_after_tax_addback,reinvestment:row.net_reinvestment,fcff:row.fcff_after_legacy_adjustment,discountFactor:row.discount_factor,pv:row.fcff_after_legacy_adjustment/row.discount_factor,derivedSalesCapital:row.net_reinvestment?delta/row.net_reinvestment:null,enteredReinvestment:d.annual[i].reinvestment,requiredInvestment:row.required_reinvestment,investmentFloorTopUp:0};});
 return {ticker:'RMBS',currency:'USD',informationAsOf:d.informationAsOf,discountOrigin:d.discountOrigin,rows,terminal:{...v.terminal,fcffGrowth:rows.at(-1).fcff?v.terminal.fcff/rows.at(-1).fcff-1:null},forecastPV:v.forecastPV,terminalPV:v.terminalPV,enterprise:v.enterprise_value_after_legacy_adjustment,terminalShare:v.terminal_pv_fraction,peakEconomicDeficit:v.peakEconomicDeficit,negativeFCFFYears:rows.filter(r=>r.fcff<0).length,warnings:Object.values(r.prose).map(x=>x.en),rmbsAllocation:v,minimumModeledLiquidity:v.minimum_liquidity_after_reserves??null,classification:r.prose.scope.en,currentValuationEligible:false,historicalBacktestEligible:false};
}
export function calculateRmbsBridge(d,enterprise,options={}){
 const {r,result:v}=rmbsContext(d);if(Object.keys(options).some(k=>!['calculationDate','outputCurrency','securityBasis','informationAsOf'].includes(k))||options.calculationDate&&options.calculationDate!=='2026-06-30'||options.outputCurrency&&options.outputCurrency!=='USD'||options.informationAsOf&&options.informationAsOf!==d.informationAsOf||options.securityBasis&&options.securityBasis!=='ordinary-common'||!finite(enterprise)||Math.abs(enterprise-v.enterprise_value_after_legacy_adjustment)>Math.max(1e-8,Math.abs(enterprise)*1e-10))fail();
 const eligible=v.conditional_share_value!==null,reason=v.status==='AWARD_POLICY_SELECTION_REQUIRED'?r.prose.awards.en:r.prose.funding.en;
 return {ticker:'RMBS',modelId:r.identity.version,currency:'USD',moneyUnit:'millions',enterprise,operatingEV:enterprise,status:eligible?'conditional':'operating-only',eligible,perShare:v.conditional_share_value,rawPerShare:v.conditional_share_value,equity:eligible?v.ordinary_equity_allocation:null,flooredPerShare:v.conditional_share_value,currentPriceTarget:null,current_price_target:null,currentQuote:null,unconditionalPerShare:null,currentCapitalVerified:false,priceComparisonEligible:false,asKnownBacktestEligible:false,claimRepricedPerTrial:d.rmbsAwardPolicy!==null,allocationLabel:'June 30 conditional common allocation · selected award policy',classification:r.prose.scope.en,referenceDate:'2026-06-30',capitalReferenceDate:'2026-06-30',shareReferenceDate:'2026-06-30',discountOrigin:d.discountOrigin,calculationDate:'2026-06-30',informationAsOf:d.informationAsOf,securityBasis:r.bridge.shareBasis,claimCompleteness:r.bridge.claimCompleteness,sources:[{url:r.bridge.sourceUrl,date:'2026-06-30'}],warnings:[r.prose.scope.en,r.prose.awards.en,r.prose.funding.en],unresolved:[r.prose.claims.en],reasons:eligible?[]:[reason],basicShares:r.sourceInputs.initial_common_shares,allocationShares:r.sourceInputs.initial_common_shares,rows:[],assetTotal:r.sourceInputs.cash_and_securities,claimTotal:r.sourceInputs.operating_cash_reserve+r.sourceInputs.eda_debt_like_claim+r.sourceInputs.other_claim_reserve,inputs:{},optionDefinitions:[],rmbsAllocation:v};
}
export function rmbsSensitivity(d){const op=calculateRmbsOperating(d);return {base:op.enterprise,normalized:op.enterprise,normalizationDelta:0,normalizedTerminalFCFFGrowth:op.terminal.fcffGrowth,normalizationLabel:'RMBS retains both investment floors; no automatic repair.',rates:[-.01,0,.01].map(shift=>{const x=structuredClone(d);x.annual.forEach(r=>r.wacc+=shift);x.terminal.wacc+=shift;try{return {waccShift:shift,wacc:x.terminal.wacc,enterprise:calculateRmbsOperating(x).enterprise};}catch(e){return {waccShift:shift,wacc:x.terminal.wacc,enterprise:null,error:e.message};}})};}
